545	  private _getActiveModelForCurrentTurn(): string {
546	    if (this.currentSequenceModel) {
547	      return this.currentSequenceModel;
548	    }
549	
550	    // Availability logic: The configured model is the source of truth,
551	    // including any permanent fallbacks (config.setModel) or manual overrides.
552	    return resolveModel(
553	      this.config.getActiveModel(),
554	      this.config.getGemini31LaunchedSync?.() ?? false,
555	    );
