558	  private async *processTurn(
559	    request: PartListUnion,
560	    signal: AbortSignal,
561	    prompt_id: string,
562	    boundedTurns: number,
563	    isInvalidStreamRetry: boolean,
564	    displayContent?: PartListUnion,
565	  ): AsyncGenerator<ServerGeminiStreamEvent, Turn> {
566	    // Re-initialize turn (it was empty before if in loop, or new instance)
567	    let turn = new Turn(this.getChat(), prompt_id);
568	
569	    this.sessionTurnCount++;
570	    if (
571	      this.config.getMaxSessionTurns() > 0 &&
572	      this.sessionTurnCount > this.config.getMaxSessionTurns()
573	    ) {
574	      yield { type: GeminiEventType.MaxSessionTurns };
575	      return turn;
576	    }
577	
578	    if (!boundedTurns) {
579	      return turn;
580	    }
581	
582	    // Check for context window overflow
583	    const modelForLimitCheck = this._getActiveModelForCurrentTurn();
584	
585	    const compressed = await this.tryCompressChat(prompt_id, false);
586	
587	    if (compressed.compressionStatus === CompressionStatus.COMPRESSED) {
588	      yield { type: GeminiEventType.ChatCompressed, value: compressed };
589	    }
590	
591	    const remainingTokenCount =
592	      tokenLimit(modelForLimitCheck) - this.getChat().getLastPromptTokenCount();
593	
594	    await this.tryMaskToolOutputs(this.getHistory());
595	
596	    // Estimate tokens. For text-only requests, we estimate based on character length.
597	    // For requests with non-text parts (like images, tools), we use the countTokens API.
598	    const estimatedRequestTokenCount = await calculateRequestTokenCount(
599	      request,
600	      this.getContentGeneratorOrFail(),
601	      modelForLimitCheck,
602	    );
603	
604	    if (estimatedRequestTokenCount > remainingTokenCount) {
605	      yield {
606	        type: GeminiEventType.ContextWindowWillOverflow,
607	        value: { estimatedRequestTokenCount, remainingTokenCount },
608	      };
609	      return turn;
610	    }
611	
612	    // Prevent context updates from being sent while a tool call is
613	    // waiting for a response. The Gemini API requires that a functionResponse
614	    // part from the user immediately follows a functionCall part from the model
615	    // in the conversation history . The IDE context is not discarded; it will
616	    // be included in the next regular message sent to the model.
617	    const history = this.getHistory();
618	    const lastMessage =
619	      history.length > 0 ? history[history.length - 1] : undefined;
620	    const hasPendingToolCall =
621	      !!lastMessage &&
622	      lastMessage.role === 'model' &&
623	      (lastMessage.parts?.some((p) => 'functionCall' in p) || false);
624	
625	    if (this.config.getIdeMode() && !hasPendingToolCall) {
626	      const { contextParts, newIdeContext } = this.getIdeContextParts(
627	        this.forceFullIdeContext || history.length === 0,
628	      );
629	      if (contextParts.length > 0) {
630	        this.getChat().addHistory({
631	          role: 'user',
632	          parts: [{ text: contextParts.join('\n') }],
633	        });
634	      }
635	      this.lastSentIdeContext = newIdeContext;
636	      this.forceFullIdeContext = false;
637	    }
638	
639	    // Re-initialize turn with fresh history
640	    turn = new Turn(this.getChat(), prompt_id);
641	
642	    const controller = new AbortController();
643	    const linkedSignal = AbortSignal.any([signal, controller.signal]);
644	
645	    const loopDetected = await this.loopDetector.turnStarted(signal);
646	    if (loopDetected) {
647	      yield { type: GeminiEventType.LoopDetected };
648	      return turn;
649	    }
650	
651	    const routingContext: RoutingContext = {
652	      history: this.getChat().getHistory(/*curated=*/ true),
653	      request,
654	      signal,
655	      requestedModel: this.config.getModel(),
656	    };
657	
658	    let modelToUse: string;
659	
660	    // Determine Model (Stickiness vs. Routing)
661	    if (this.currentSequenceModel) {
662	      modelToUse = this.currentSequenceModel;
663	    } else {
664	      const router = this.config.getModelRouterService();
665	      const decision = await router.route(routingContext);
666	      modelToUse = decision.model;
667	    }
668	
669	    // availability logic
670	    const modelConfigKey: ModelConfigKey = {
671	      model: modelToUse,
672	      isChatModel: true,
673	    };
674	    const { model: finalModel } = applyModelSelection(
675	      this.config,
676	      modelConfigKey,
677	      { consumeAttempt: false },
678	    );
679	    modelToUse = finalModel;
680	
681	    if (!signal.aborted && !this.currentSequenceModel) {
682	      yield { type: GeminiEventType.ModelInfo, value: modelToUse };
683	    }
684	    this.currentSequenceModel = modelToUse;
685	
686	    // Update tools with the final modelId to ensure model-dependent descriptions are used.
687	    await this.setTools(modelToUse);
688	
689	    const resultStream = turn.run(
690	      modelConfigKey,
691	      request,
692	      linkedSignal,
693	      displayContent,
694	    );
695	    let isError = false;
696	    let isInvalidStream = false;
697	
698	    for await (const event of resultStream) {
