702	        return turn;
703	      }
704	      yield event;
705	
706	      this.updateTelemetryTokenCount();
707	
708	      if (event.type === GeminiEventType.InvalidStream) {
709	        isInvalidStream = true;
710	      }
711	      if (event.type === GeminiEventType.Error) {
712	        isError = true;
713	      }
714	    }
715	
716	    if (isError) {
717	      return turn;
718	    }
